SELECT inventory.id, inventory.last_restock, inventory.product_id, store_sales.product_id AS store_sale_product_id, store_sales.units, store_sales.store_id, CASE WHEN store_sales.revenue >= 3400 THEN 'High' WHEN store_sales.revenue >= 1100 THEN 'Medium' ELSE 'Low' END AS revenue_band FROM inventory INNER JOIN store_sales ON inventory.store_id = store_sales.store_id AND inventory.product_id = store_sales.product_id WHERE store_sales.sale_date >= '2025-05-01' AND inventory.quantity > 204 ORDER BY id DESC;
